// Multi-course architecture: two independent courses are generated by the same builder, published
// side by side, and stay isolated. The second course (vi_en_mini) is built in memory from its
// committed source tables, so this test never writes into content/ and never touches vi_en's 512
// committed bundles.
import test from 'node:test';
import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import { loadKit, root } from './helpers/kit.mjs';
import { buildCourse } from '../../../tools/content/build-course.mjs';
import { layeredMedia, withFixtureMedia } from './helpers/media-course.mjs';

const kit = await loadKit('multi-course');
const local = kit.loadLocalContent(root);

const SECOND = 'vi_en_mini';
// vi_en_mini ships no media, so the builder declares placeholder hashes for it; the publish gate
// would refuse those. withFixtureMedia re-declares them with real (fixture) bytes.
const viEnMedia = kit.localMediaStore(root);
const built = new Map();
const fixtureMedia = new Map();
for (const version of ['v1', 'v2']) {
  const b = await withFixtureMedia(
    kit,
    await buildCourse({ courseId: SECOND, version }),
    viEnMedia,
  );
  built.set(version, b);
  for (const [fileId, bytes] of b.served) fixtureMedia.set(fileId, bytes);
}

// The fixture's bundle texts, served alongside the committed vi_en files. Nothing is written to disk:
// buildCourse() returns the files, and only the CLI entry point writes them.
const fixtureTexts = new Map();
for (const b of built.values())
  for (const file of b.files) fixtureTexts.set(file.fileId, file.text);
const files = {
  async read(fileId) {
    if (fixtureTexts.has(fileId)) return fixtureTexts.get(fileId);
    return local.files.read(fileId);
  },
  // vi_en's committed media plus the fixture course's own files.
  ...layeredMedia(viEnMedia, fixtureMedia),
};

const viEn = local.publications.find((p) => p.courseId === 'vi_en');

async function publish(app, b, expectedPublishedVersion = null, overrides = {}) {
  return app.call('POST', '/v1/admin/content-versions', {
    user: 'maintainer-1',
    body: {
      courseId: b.publish.courseId,
      versionId: b.publish.versionId,
      manifestFileId: b.publish.manifestFileId,
      manifestSha256: b.publish.manifestSha256,
      expectedPublishedVersion,
      ...overrides,
    },
    key: randomUUID(),
  });
}

/** vi_en seeded (the shipped course) plus vi_en_mini v1 and v2 published through the real route. */
async function appWithBothCourses(options = {}) {
  const app = await kit.createTestApp({ root, files, ...options });
  assert.equal((await publish(app, built.get('v1'))).status, 200, 'fixture v1 publishes');
  assert.equal((await publish(app, built.get('v2'), 'v1')).status, 200, 'fixture v2 publishes');
  return app;
}

test('both courses build from their own tables: separate manifests, bundles and signatures', () => {
  const v1 = built.get('v1');
  const v2 = built.get('v2');
  for (const b of [v1, v2]) assert.deepEqual(b.problems, []);

  assert.deepEqual([v1.manifest.courseId, v1.manifest.courseVersion], [SECOND, 'v1']);
  assert.deepEqual([v2.manifest.courseId, v2.manifest.courseVersion], [SECOND, 'v2']);
  assert.equal(v1.manifest.units.length, 1);
  assert.equal(v1.manifest.nodes.length, 8);
  assert.equal(v1.finished.length, 32, '32 lessons per unit');

  // Same tables, different version: the structure hash and every fileId carry the version.
  assert.notEqual(v1.manifest.manifestHash, v2.manifest.manifestHash);
  assert.deepEqual(
    v1.manifest.bundles.map((b) => b.lessonId),
    v2.manifest.bundles.map((b) => b.lessonId),
    'the same lessonIds exist in both versions — version isolation cannot rely on ids',
  );
  for (const b of [v1, v2]) {
    const prefix = `${SECOND}.${b.publish.versionId}.`;
    assert.ok(
      b.publish.files.every((f) => f.fileId.startsWith(prefix)),
      prefix,
    );
    assert.equal(b.publish.manifestFileId, `${prefix}manifest`);
  }
  // No fileId is shared with the shipped course, so publishing one can never overwrite the other.
  const viEnFiles = new Set(
    local.publications.filter((p) => p.courseId === 'vi_en').map((p) => p.manifestFileId),
  );
  assert.equal([...viEnFiles].filter((id) => fixtureTexts.has(id)).length, 0);
  assert.equal(v1.publish.files.filter((f) => viEnFiles.has(f.fileId)).length, 0);
});

test('two courses live side by side: /v1/courses lists both, each manifest and lesson resolves', async () => {
  const app = await appWithBothCourses();

  const courses = (await app.call('GET', '/v1/courses', { user: 'learner' })).body;
  assert.deepEqual(
    courses.items.map((c) => [c.courseId, c.publishedVersion]),
    [
      ['vi_en', 'v2'],
      [SECOND, 'v2'],
    ],
  );

  // The shipped course is untouched by the second one.
  const shipped = (await app.call('GET', '/v1/courses/vi_en/manifest', { user: 'learner' })).body;
  assert.deepEqual(
    [shipped.courseId, shipped.courseVersion, shipped.units.length, shipped.bundles.length],
    ['vi_en', 'v2', 16, 512],
  );

  const second = (await app.call('GET', `/v1/courses/${SECOND}/manifest`, { user: 'learner' }))
    .body;
  assert.deepEqual(
    [second.courseId, second.courseVersion, second.units.length, second.bundles.length],
    [SECOND, 'v2', 1, 32],
  );
  assert.notEqual(second.manifestHash, shipped.manifestHash);

  // A lessonId is only unique inside a course. Both courses answer to `u1n1l1`. The legacy,
  // course-less endpoint must NOT silently pick one: it refuses the ambiguous request so Mobile
  // can never open course B and receive course A's bundle.
  const ambiguous = await app.call('GET', '/v1/lessons/u1n1l1/bundle', { user: 'learner' });
  assert.equal(ambiguous.status, 409);
  assert.equal(ambiguous.body.error.code, 'LESSON_AMBIGUOUS');
  assert.deepEqual(
    [...ambiguous.body.error.details.courseIds].sort(),
    ['vi_en', SECOND],
    'both courses that own u1n1l1 are reported, never guessed',
  );

  // The course-scoped route resolves each course's own bundle deterministically — the only
  // authoritative way to fetch a lesson once more than one course shares its lessonId.
  const shippedLesson = await app.call('GET', '/v1/courses/vi_en/lessons/u1n1l1/bundle', {
    user: 'learner',
  });
  assert.equal(shippedLesson.status, 200);
  assert.equal(shippedLesson.body.courseId, 'vi_en');
  assert.equal(shippedLesson.body.courseVersion, 'v2');

  const secondLesson = await app.call('GET', `/v1/courses/${SECOND}/lessons/u1n1l1/bundle`, {
    user: 'learner',
  });
  assert.equal(secondLesson.status, 200);
  assert.equal(secondLesson.body.courseId, SECOND);
  assert.equal(secondLesson.body.courseVersion, 'v2');

  // Same lessonId, two courses: the bundles are genuinely different content — no collision leaks.
  assert.notDeepEqual(shippedLesson.body, secondLesson.body);

  // The fixture's own bundle is reachable by its version-scoped fileId through the manifest index.
  const index = second.bundles.find((b) => b.lessonId === 'u1n1l1');
  assert.equal(index.fileId, `${SECOND}.v2.u1n1l1`);
  assert.ok(index.sha256.length === 64);
});

test('collision rule: legacy endpoint refuses ambiguity, course-scoped route is authoritative', async () => {
  const app = await appWithBothCourses();

  // Ambiguous: the lessonId exists in more than one published course.
  const legacy = await app.call('GET', '/v1/lessons/u1n1l1/bundle', { user: 'learner' });
  assert.equal(legacy.status, 409);
  assert.equal(legacy.body.error.code, 'LESSON_AMBIGUOUS');
  assert.deepEqual([...legacy.body.error.details.courseIds].sort(), ['vi_en', SECOND]);

  // Course-scoped is the only safe path and always returns that course's own content.
  for (const courseId of ['vi_en', SECOND]) {
    const b = await app.call('GET', `/v1/courses/${courseId}/lessons/u1n1l1/bundle`, {
      user: 'learner',
    });
    assert.equal(b.status, 200);
    assert.equal(b.body.courseId, courseId);
  }

  // A lessonId owned by exactly one course is still served by the legacy route (non-ambiguous).
  const unique = await app.call('GET', '/v1/lessons/u16n8l1/bundle', { user: 'learner' });
  assert.equal(unique.status, 200);
  assert.equal(unique.body.courseId, 'vi_en');
});

test('version isolation: publishing v2 moves only that course pointer; v1 stays fetchable by version', async () => {
  const app = await appWithBothCourses();

  const pinned = (
    await app.call('GET', `/v1/courses/${SECOND}/manifest`, {
      user: 'learner',
      query: 'version=v1',
    })
  ).body;
  assert.equal(pinned.courseVersion, 'v1');
  const current = (await app.call('GET', `/v1/courses/${SECOND}/manifest`, { user: 'learner' }))
    .body;
  assert.equal(current.courseVersion, 'v2');
  assert.notEqual(pinned.manifestHash, current.manifestHash);

  // vi_en is still pinned to its own version.
  const shipped = (
    await app.call('GET', '/v1/courses/vi_en/manifest', { user: 'learner', query: 'version=v2' })
  ).body;
  assert.equal(shipped.courseVersion, 'v2');

  // A stale pointer is refused for the second course exactly like the first.
  const stale = await publish(app, built.get('v1'), null);
  assert.deepEqual(
    [stale.status, stale.body.error.code, stale.body.error.details.publishedVersion],
    [409, 'REVISION_CONFLICT', 'v2'],
  );
  // And a version can only be published once.
  const dup = await publish(app, built.get('v1'), 'v2');
  assert.equal(dup.body.error.details.reason, 'VERSION_EXISTS');
});

test('content integrity is per course: a tampered second-course bundle is refused and nothing flips', async () => {
  const tampered = new Map(fixtureTexts);
  const victim = `${SECOND}.v1.u1n1l1`;
  tampered.set(victim, tampered.get(victim).replace('"title":"', '"title":"X'));
  const app = await kit.createTestApp({
    root,
    files: {
      async read(fileId) {
        if (tampered.has(fileId)) return tampered.get(fileId);
        return local.files.read(fileId);
      },
      ...layeredMedia(viEnMedia, fixtureMedia),
    },
  });

  const refused = await publish(app, built.get('v1'));
  assert.deepEqual(
    [refused.status, refused.body.error.code],
    [400, 'VALIDATION_ERROR'],
    JSON.stringify(refused.body),
  );

  const courses = (await app.call('GET', '/v1/courses', { user: 'learner' })).body;
  assert.deepEqual(
    courses.items.map((c) => c.courseId),
    ['vi_en'],
    'the shipped course still serves and the refused one never appears',
  );
  assert.equal(
    (await app.call('GET', '/v1/lessons/u1n1l1/bundle', { user: 'learner' })).status,
    200,
  );
});

test('the shipped course still publishes with exactly the committed 512 bundles', async () => {
  const app = await kit.createTestApp({ root, files, seed: false });
  const ok = await app.call('POST', '/v1/admin/content-versions', {
    user: 'maintainer-1',
    body: { ...viEn, expectedPublishedVersion: null },
    key: randomUUID(),
  });
  assert.equal(ok.status, 200, JSON.stringify(ok.body));
  const manifest = (await app.call('GET', '/v1/courses/vi_en/manifest', { user: 'learner' })).body;
  assert.equal(manifest.bundles.length, 512);
  assert.equal(manifest.units.length, 16);
});
